# ---- cell 2
from importlib.metadata import PackageNotFoundError, version
import subprocess
import sys

REQUIRED_ENGINE = "1.32.7"
try:
    installed_engine = version("kaggle-environments")
except PackageNotFoundError:
    installed_engine = None
if installed_engine != REQUIRED_ENGINE:
    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", f"kaggle-environments=={REQUIRED_ENGINE}"])
print("kaggle-environments", version("kaggle-environments"))


# ---- cell 3
from pathlib import Path
import json
import os
import sys

WORK = Path("/kaggle/working") if Path("/kaggle/working").is_dir() else Path.cwd()
WORK.mkdir(parents=True, exist_ok=True)
os.chdir(WORK)
sys.path.insert(0, str(WORK))
print("workdir", WORK)


